/** The subset of the Lottie schema the wrappers read. */
export type LottieJson = {op: number; w: number; h: number}

export type IllustrationName = keyof typeof ILLUSTRATIONS

export type IllustrationProps = {
  name: IllustrationName
  /** Width in px; the art is square. */
  size: number
  /** Defaults to the animation's own setting (loops for empty states, once for success). */
  loop?: boolean
  testID?: string
}
